import math

def skjkasdkd(lst):
    """You are given a list of integers.
    You need to find the largest prime value and return the sum of its digits.
    If no prime exists in the list, return 0.
    """
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        # check 6k ± 1 up to sqrt(n)
        limit = int(math.isqrt(n))
        i = 5
        while i <= limit:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    max_prime = None
    for x in lst:
        if x > 1 and is_prime(x):
            if max_prime is None or x > max_prime:
                max_prime = x

    if max_prime is None:
        return 0

    # Sum digits of the maximum prime
    s = 0
    n = max_prime
    while n:
        s += n % 10
        n //= 10
    return s
